1	package chainledger
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	)
8	
9	func commonNames(found []CommonUpstream) []string {
10		names := make([]string, len(found))
11		for i, c := range found {
12			names[i] = c.Dataset
13		}
14		return names
15	}
16	
17	func mustCommon(t *testing.T, graph map[string]*Lineage, first, second string) []CommonUpstream {
18		t.Helper()
19		found, err := CommonUpstreams(graph, first, second)
20		if err != nil {
21			t.Fatalf("CommonUpstreams(%s, %s): %v", first, second, err)
22		}
23		return found
24	}
25	
26	func assertCommon(t *testing.T, found []CommonUpstream, name string,
27		wantDistFirst int, wantPathFirst []string, wantDistSecond int, wantPathSecond []string) {
28		t.Helper()
29		for _, c := range found {
30			if c.Dataset != name {
31				continue
32			}
33			if c.DistanceToFirst != wantDistFirst || c.DistanceToSecond != wantDistSecond {
34				t.Errorf("common %s distances = (%d,%d), want (%d,%d)",
35					name, c.DistanceToFirst, c.DistanceToSecond, wantDistFirst, wantDistSecond)
36			}
37			if !sameStrings(c.PathToFirst, wantPathFirst) {
38				t.Errorf("common %s path-to-first = %v, want %v", name, c.PathToFirst, wantPathFirst)
39			}
40			if !sameStrings(c.PathToSecond, wantPathSecond) {
41				t.Errorf("common %s path-to-second = %v, want %v", name, c.PathToSecond, wantPathSecond)
42			}
43			return
44		}
45		t.Fatalf("common source %q missing from %v", name, commonNames(found))
46	}
47	
48	// assertEachCommonOnce checks every source appears exactly once in the result.
49	func assertEachCommonOnce(t *testing.T, found []CommonUpstream) {
50		t.Helper()
51		seen := map[string]int{}
52		for _, c := range found {
53			seen[c.Dataset]++
54		}
55		for name, count := range seen {
56			if count > 1 {
57				t.Fatalf("common source %q appears %d times in %v, want exactly once",
58					name, count, commonNames(found))
59			}
60		}
61	}
62	
63	// The worked example from the spec: raw derives a and b; a and b both take
64	// part in deriving left and right. Querying left and right returns a and b and
65	// excludes raw, because a and b are later common sources standing downstream of
66	// raw.
67	func TestCommonUpstreamsFrontierExcludesEarlierSharedRoot(t *testing.T) {
68		graph := buildRegisteredGraph(t, [][]string{
69			{"raw"},
70			{"a", "raw"},
71			{"b", "raw"},
72			{"left", "a", "b"},
73			{"right", "a", "b"},
74		})
75	
76		found := mustCommon(t, graph, "left", "right")
77		if got, want := commonNames(found), []string{"a", "b"}; !reflect.DeepEqual(got, want) {
78			t.Fatalf("common sources = %v, want %v (raw must be hidden behind a and b)", got, want)
79		}
80		assertEachCommonOnce(t, found)
81		assertCommon(t, found, "a", 1, []string{"a", "left"}, 1, []string{"a", "right"})
82		assertCommon(t, found, "b", 1, []string{"b", "left"}, 1, []string{"b", "right"})
83	}
84	
85	// Even when raw participates directly in both targets' derivation and is fewer
86	// edges away, it is still excluded: distance never overrides the frontier rule.
87	func TestCommonUpstreamsDirectShorterEdgeDoesNotRescueHiddenSource(t *testing.T) {
88		graph := buildRegisteredGraph(t, [][]string{
89			{"raw"},
90			{"a", "raw"},
91			{"b", "raw"},
92			// Both targets take raw directly (distance 1) AND through a and b.
93			{"left", "raw", "a", "b"},
94			{"right", "raw", "a", "b"},
95		})
96	
97		found := mustCommon(t, graph, "left", "right")
98		if got, want := commonNames(found), []string{"a", "b"}; !reflect.DeepEqual(got, want) {
99			t.Fatalf("common sources = %v, want %v (shorter raw edge must not un-hide it)", got, want)
100		}
101		assertEachCommonOnce(t, found)
102		assertCommon(t, found, "a", 1, []string{"a", "left"}, 1, []string{"a", "right"})
103		assertCommon(t, found, "b", 1, []string{"b", "left"}, 1, []string{"b", "right"})
104	}
105	
106	// raw is hidden even when only ONE of the two later shared points lies on a
107	// path through it — a single later common source downstream of raw is enough.
108	func TestCommonUpstreamsOneLaterSharedPointStillHidesRoot(t *testing.T) {
109		graph := buildRegisteredGraph(t, [][]string{
110			{"raw"},
111			{"a", "raw"},
112			// left depends on a directly; right reaches a through mid.
113			{"mid", "a"},
114			{"left", "a"},
115			{"right", "a", "mid"},
116		})
117		// right's parents a and mid: mid is downstream of a, but that does not make
118		// the graph cyclic (a -> mid -> right, a -> left).
119	
120		found := mustCommon(t, graph, "left", "right")
121		if got, want := commonNames(found), []string{"a"}; !reflect.DeepEqual(got, want) {
122			t.Fatalf("common sources = %v, want %v (raw hidden behind a alone)", got, want)
123		}
124		assertCommon(t, found, "a", 1, []string{"a", "left"}, 1, []string{"a", "right"})
125	}
