127	// Querying a dataset with itself returns just that dataset, both distances
128	// zero and both paths only its own name.
129	func TestCommonUpstreamsSameTargetIsSelf(t *testing.T) {
130		graph := buildRegisteredGraph(t, [][]string{
131			{"raw"},
132			{"a", "raw"},
133			{"b", "raw"},
134			{"only", "a", "b"},
135		})
136	
137		found := mustCommon(t, graph, "only", "only")
138		if got, want := commonNames(found), []string{"only"}; !reflect.DeepEqual(got, want) {
139			t.Fatalf("same target: common sources = %v, want %v", got, want)
140		}
141		assertCommon(t, found, "only", 0, []string{"only"}, 0, []string{"only"})
142	
143		// A target with ancestors queried against itself still reports only itself:
144		// a and raw are common by closure but hidden behind the target.
145		found = mustCommon(t, graph, "a", "a")
146		if got, want := commonNames(found), []string{"a"}; !reflect.DeepEqual(got, want) {
147			t.Fatalf("same non-root target: common sources = %v, want %v", got, want)
148		}
149		assertCommon(t, found, "a", 0, []string{"a"}, 0, []string{"a"})
150	
151		// A root queried against itself is the same single zero-distance record.
152		found = mustCommon(t, graph, "raw", "raw")
153		if got, want := commonNames(found), []string{"raw"}; !reflect.DeepEqual(got, want) {
154			t.Fatalf("same root target: common sources = %v, want %v", got, want)
155		}
156		assertCommon(t, found, "raw", 0, []string{"raw"}, 0, []string{"raw"})
157	}
