159	// When one target is an upstream of the other, the sole result is that
160	// upstream target with distance zero on its own side; its own ancestors are
161	// hidden behind it.
162	func TestCommonUpstreamsOneTargetUpstreamOfOther(t *testing.T) {
163		graph := buildRegisteredGraph(t, [][]string{
164			{"raw"},
165			{"mid", "raw"},
166			{"leaf", "mid"},
167		})
168	
169		// First target is the upstream.
170		found := mustCommon(t, graph, "mid", "leaf")
171		if got, want := commonNames(found), []string{"mid"}; !reflect.DeepEqual(got, want) {
172			t.Fatalf("upstream first: common sources = %v, want %v", got, want)
173		}
174		assertCommon(t, found, "mid", 0, []string{"mid"}, 1, []string{"mid", "leaf"})
175	
176		// Swapped inputs swap the two sides; the result is otherwise the same.
177		found = mustCommon(t, graph, "leaf", "mid")
178		if got, want := commonNames(found), []string{"mid"}; !reflect.DeepEqual(got, want) {
179			t.Fatalf("upstream second: common sources = %v, want %v", got, want)
180		}
181		assertCommon(t, found, "mid", 1, []string{"mid", "leaf"}, 0, []string{"mid"})
182	
183		// Several levels apart: raw is hidden behind the nearer target mid.
184		found = mustCommon(t, graph, "raw", "leaf")
185		if got, want := commonNames(found), []string{"raw"}; !reflect.DeepEqual(got, want) {
186			t.Fatalf("root vs descendant: common sources = %v, want %v", got, want)
187		}
188		assertCommon(t, found, "raw", 0, []string{"raw"}, 2, []string{"raw", "mid", "leaf"})
189	}
