191	// Two lineages with no shared source succeed with a non-nil empty list.
192	func TestCommonUpstreamsNoSharedSourcesEmptyButNonNil(t *testing.T) {
193		graph := buildRegisteredGraph(t, [][]string{
194			{"rootA"},
195			{"a1", "rootA"},
196			{"rootB"},
197			{"b1", "rootB"},
198			{"lonely"},
199		})
200	
201		// Two independent roots.
202		found, err := CommonUpstreams(graph, "rootA", "rootB")
203		if err != nil {
204			t.Fatalf("unrelated roots: %v", err)
205		}
206		if found == nil || len(found) != 0 {
207			t.Fatalf("unrelated roots: want empty non-nil list, got %v", found)
208		}
209	
210		// A root and an unrelated derived dataset.
211		found, err = CommonUpstreams(graph, "lonely", "b1")
212		if err != nil {
213			t.Fatalf("lonely vs derived: %v", err)
214		}
215		if found == nil || len(found) != 0 {
216			t.Fatalf("lonely vs derived: want empty non-nil list, got %v", found)
217		}
218	
219		// Two leaves on separate branches.
220		found = mustCommon(t, graph, "a1", "b1")
221		if found == nil || len(found) != 0 {
222			t.Fatalf("separate branches: want empty non-nil list, got %v", found)
223		}
224	}
