226	// Multiple frontier sources are returned together, not chosen by distance: a
227	// shared source that is itself a root and a separate shared intermediate point
228	// can coexist as long as no common node lies strictly downstream of another.
229	func TestCommonUpstreamsMultipleFrontierSourcesNotPickedByDistance(t *testing.T) {
230		// Both targets share the deep branch through d -> c -> a, and independently
231		// share the root b directly. Neither frontier point is downstream of the
232		// other, so both are returned.
233		graph := buildRegisteredGraph(t, [][]string{
234			{"a"},
235			{"b"},
236			{"c", "a"},
237			{"d", "c"},
238			{"left", "b", "d"},
239			{"right", "b", "d"},
240		})
241	
242		found := mustCommon(t, graph, "left", "right")
243		if got, want := commonNames(found), []string{"b", "d"}; !reflect.DeepEqual(got, want) {
244			t.Fatalf("common sources = %v, want %v", got, want)
245		}
246		assertEachCommonOnce(t, found)
247		// b is at distance 1; d at distance 1 too, but a and c are hidden behind d.
248		assertCommon(t, found, "b", 1, []string{"b", "left"}, 1, []string{"b", "right"})
249		assertCommon(t, found, "d", 1, []string{"d", "left"}, 1, []string{"d", "right"})
250	}
251	
252	// Two later common sources can have crossing routes: each one reaches the
253	// targets over different edges, and neither lies downstream of the other on a
254	// common path. Both are then kept (with asymmetric distances) while the shared
255	// root behind them is hidden.
256	func TestCommonUpstreamsCrossingFrontierBothKept(t *testing.T) {
257		// s derives c and d. c reaches left via x and right directly; d reaches
258		// left directly and right via y.
259		//
260		//   s ──> c ──> x ──> left       c ──> right
261		//    └──> d ──────────> left     d ──> y ──> right
262		graph := buildRegisteredGraph(t, [][]string{
263			{"s"},
264			{"c", "s"},
265			{"d", "s"},
266			{"x", "c"},
267			{"y", "d"},
268			{"left", "x", "d"},
269			{"right", "c", "y"},
270		})
271	
272		found := mustCommon(t, graph, "left", "right")
273		if got, want := commonNames(found), []string{"c", "d"}; !reflect.DeepEqual(got, want) {
274			t.Fatalf("common sources = %v, want %v (s hidden behind both, c and d kept)", got, want)
275		}
276		assertEachCommonOnce(t, found)
277		// No common child edge hides c or d: c's children (x, right) and d's
278		// children (left, y) are all non-common.
279		assertCommon(t, found, "c", 2, []string{"c", "x", "left"}, 1, []string{"c", "right"})
280		assertCommon(t, found, "d", 1, []string{"d", "left"}, 2, []string{"d", "y", "right"})
281	}
