283	// Results are ordered by source name in Go string order, never by distance or
284	// registration order.
285	func TestCommonUpstreamsOrderedByName(t *testing.T) {
286		graph := buildRegisteredGraph(t, [][]string{
287			{"zeta"},
288			{"alpha"},
289			{"mid"},
290			{"left", "zeta", "alpha", "mid"},
291			{"right", "mid", "zeta", "alpha"},
292		})
293	
294		found := mustCommon(t, graph, "left", "right")
295		if got, want := commonNames(found), []string{"alpha", "mid", "zeta"}; !reflect.DeepEqual(got, want) {
296			t.Fatalf("common source order = %v, want %v", got, want)
297		}
298		assertEachCommonOnce(t, found)
299	}
