301	// The two sides can have different distances and different explanation paths:
302	// each side is traced independently from its own target.
303	func TestCommonUpstreamsAsymmetricSides(t *testing.T) {
304		// shared reaches left over one hop and right over a longer detour.
305		graph := buildRegisteredGraph(t, [][]string{
306			{"shared"},
307			{"x", "shared"},
308			{"left", "shared"},
309			{"right", "x"},
310		})
311	
312		found := mustCommon(t, graph, "left", "right")
313		if got, want := commonNames(found), []string{"shared"}; !reflect.DeepEqual(got, want) {
314			t.Fatalf("common sources = %v, want %v", got, want)
315		}
316		assertCommon(t, found, "shared",
317			1, []string{"shared", "left"},
318			2, []string{"shared", "x", "right"})
319	
320		// Swapping the query swaps both sides field by field.
321		found = mustCommon(t, graph, "right", "left")
322		assertCommon(t, found, "shared",
323			2, []string{"shared", "x", "right"},
324			1, []string{"shared", "left"})
325	}
