353	// Paths are computed against the current edges: replacing a direct upstream
354	// lengthens the distance and re-derives the explanation on that side, while
355	// the other side and the frontier membership stay consistent.
356	func TestCommonUpstreamsReflectReregister(t *testing.T) {
357		graph := buildRegisteredGraph(t, [][]string{
358			{"raw"},
359			{"a", "raw"},
360			{"left", "raw", "a"},
361			{"right", "raw"},
362		})
363	
364		// Initially raw is a direct parent of both, but a is a later common source
365		// on the left side only: a is not upstream of right, so raw is the sole
366		// frontier (a is not even common).
367		found := mustCommon(t, graph, "left", "right")
368		if got, want := commonNames(found), []string{"raw"}; !reflect.DeepEqual(got, want) {
369			t.Fatalf("common sources = %v, want %v", got, want)
370		}
371		assertCommon(t, found, "raw", 1, []string{"raw", "left"}, 1, []string{"raw", "right"})
372	
373		// right now also derives through a: a becomes the later common source and
374		// raw is hidden, even though the direct raw edges remain.
375		mustRegister(t, graph, "right", "raw", "a")
376		found = mustCommon(t, graph, "left", "right")
377		if got, want := commonNames(found), []string{"a"}; !reflect.DeepEqual(got, want) {
378			t.Fatalf("after rewire common sources = %v, want %v", got, want)
379		}
380		assertCommon(t, found, "a", 1, []string{"a", "left"}, 1, []string{"a", "right"})
381	}
