865		fromNew := mustImpacts(t, graph, "newsrc")
866		if got, want := impactNames(fromNew), []string{"mid", "leaf"}; !reflect.DeepEqual(got, want) {
867			t.Fatalf("impacts from new source = %v, want %v", got, want)
868		}
